async def act(page):
    """Perform a visible search for 'DeepSeek' (use the KB helper when available), then click the bottom-most result.

    Returns the raw list returned by create_curated_collection_by_search unmodified if the helper returned data; otherwise returns None.
    """
    import re

    results = None

    # 1) Use the site-aware helper if available (required when a corresponding helper exists)
    try:
        results = await create_curated_collection_by_search(page, "DeepSeek", max_results=0, resolve_links=True)
    except Exception:
        # Helper may fail if the complementary region/search widget isn't present on '/'. We'll proceed with fallbacks.
        results = None

    # 2) If a complementary region with a search widget exists, try to use it to perform the search visibly.
    try:
        comp = page.get_by_role("complementary")
        # Try to find a search input (searchbox preferred, then textbox)
        search_input = None
        try:
            search_input = comp.get_by_role("searchbox")
            await search_input.fill("DeepSeek")
        except Exception:
            try:
                search_input = comp.get_by_role("textbox")
                await search_input.fill("DeepSeek")
            except Exception:
                search_input = None

        if search_input is not None:
            # Prefer a button whose name includes 'search'
            try:
                search_button = comp.get_by_role("button", name=re.compile("search", re.I))
                # If found, click it
                # Ensure the locator has at least one match
                if await search_button.count() > 0:
                    await search_button.nth(0).click()
                else:
                    raise Exception("No search-named button found inside complementary region")
            except Exception:
                # Fallback: click the first button inside complementary region, or press Enter in the input
                try:
                    btns = comp.get_by_role("button")
                    if await btns.count() > 0:
                        await btns.nth(0).click()
                    else:
                        # Press Enter in the input as last resort
                        await search_input.press("Enter")
                except Exception:
                    # If all fails, continue to query-string fallback below
                    pass
    except Exception:
        # complementary region not present or not usable; continue to fallback
        pass

    # 3) Locate the results region (role='main') and ensure it is settled
    main = page.get_by_role("main")
    try:
        await main.wait_for(timeout=3000)
    except Exception:
        pass

    # 4) Use accessibility-role-centric selectors with safe indexing
    # Try headings first
    headings = main.get_by_role("heading")
    try:
        heading_count = await headings.count()
    except Exception:
        heading_count = 0

    # Try articles as secondary pattern
    articles = main.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    # If no obvious results were rendered, navigate to the query-string search URL as a robust fallback
    if heading_count == 0 and article_count == 0:
        await page.goto('/?s=DeepSeek')
        main = page.get_by_role("main")
        try:
            await main.wait_for(timeout=5000)
        except Exception:
            pass
        headings = main.get_by_role("heading")
        try:
            heading_count = await headings.count()
        except Exception:
            heading_count = 0
        articles = main.get_by_role("article")
        try:
            article_count = await articles.count()
        except Exception:
            article_count = 0

    # 5) Click strategy: heading->link, then article->link, then last link in main, then last link on page
    if heading_count > 0:
        bottom_idx = heading_count - 1
        bottom_heading = main.get_by_role("heading").nth(bottom_idx)
        links_in_heading = bottom_heading.get_by_role("link")
        try:
            link_count = await links_in_heading.count()
        except Exception:
            link_count = 0

        if link_count > 0:
            # Use the full parent->child path for the click (final action)
            await main.get_by_role("heading").nth(bottom_idx).get_by_role("link").nth(link_count - 1).click()
            return results
        else:
            await bottom_heading.click()
            return results

    if article_count > 0:
        bottom_idx = article_count - 1
        bottom_article = main.get_by_role("article").nth(bottom_idx)
        links_in_article = bottom_article.get_by_role("link")
        try:
            link_count = await links_in_article.count()
        except Exception:
            link_count = 0

        if link_count > 0:
            await main.get_by_role("article").nth(bottom_idx).get_by_role("link").nth(link_count - 1).click()
            return results
        else:
            await bottom_article.click()
            return results

    # Fallback: last link inside main
    links_in_main = main.get_by_role("link")
    try:
        links_count = await links_in_main.count()
    except Exception:
        links_count = 0

    if links_count > 0:
        await links_in_main.nth(links_count - 1).click()
        return results

    # Final fallback: last link on the whole page
    all_links = page.get_by_role("link")
    try:
        all_links_count = await all_links.count()
    except Exception:
        all_links_count = 0

    if all_links_count > 0:
        await all_links.nth(all_links_count - 1).click()
        return results

    # Nothing clickable found; return the helper output (may be None)
    return results

